(6148420, 905488, 17507, '<td valign="top">lychgates? I like the photo just fine, but don''t see lychgates.</td>', 'lychgates? I like the photo just fine, but don''t see lychgates.', '2010-09-01 12:36:25.000000', NULL, 1),
(6148435, 906392, 17507, '<td valign="top">I don''t recall seeing boudoir-esque shots as a significant part of Nixter''s portfolio. On its own merit, the blown-out left leg and the accompanying jaggies are quite distracting.</td>', 'I don''t recall seeing boudoir-esque shots as a significant part of Nixter''s portfolio. On its own merit, the blown-out left leg and the accompanying jaggies are quite distracting.', '2010-09-01 12:42:01.000000', NULL, 1),
(6148437, 906816, 17507, '<td valign="top">All right, I''ll admit it--you''ve lost me with this one.</td>', 'All right, I''ll admit it--you''ve lost me with this one.', '2010-09-01 12:42:40.000000', NULL, 1),
(6148439, 906314, 17507, '<td valign="top">Very strong. B/W, use of backlit figure, full tonal range all seem topically appropriate.</td>', 'Very strong. B/W, use of backlit figure, full tonal range all seem topically appropriate.', '2010-09-01 12:43:05.000000', NULL, 1),
(6148441, 905759, 17507, '<td valign="top">Control of the exposure is less careful than I think is characteristic of Nixter.</td>', 'Control of the exposure is less careful than I think is characteristic of Nixter.', '2010-09-01 12:43:36.000000', NULL, 1),
(6148442, 906371, 17507, '<td valign="top">I like the overhead perspective and the candid-esque nature of the shot is topically appropriate, but I would have liked to see you do something to bump the whites a bit.</td>', 'I like the overhead perspective and the candid-esque nature of the shot is topically appropriate, but I would have liked to see you do something to bump the whites a bit.', '2010-09-01 12:44:23.000000', NULL, 1),
(6148447, 906394, 17507, '<td valign="top">The muted palette and choice of subject are appropriate, but it looks like you''ve lost control of the highlights on the boy''s face. You really need smoother gradients for this to work. Nixter has used vignettes, but not so much the heavy blurred-square-border vignettes.</td>', 'The muted palette and choice of subject are appropriate, but it looks like you''ve lost control of the highlights on the boy''s face. You really need smoother gradients for this to work. Nixter has used vignettes, but not so much the heavy blurred-square-border vignettes.', '2010-09-01 12:46:39.000000', NULL, 1),
(6148493, 905538, 103411, '<td valign="top">Really love this.. eyes closed... headscarf... really well set up.</td>', 'Really love this.. eyes closed... headscarf... really well set up.', '2010-09-01 13:20:17.000000', NULL, 1),
