(6149858, 905989, 112828, '<td valign="top">I think I know this style... Hope I''m not being too bold if I say this looks like it was taken with a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=53814" rel="nofollow" target="_blank">pointandshoot</a> . :)<br/> <br/>Could be wrong, but the juxtaposition of cats and some sort of blurry translucent thing just makes me strongly suspect I know who this is... :)</td>', 'I think I know this style... Hope I''m not being too bold if I say this looks like it was taken with a  pointandshoot . :) Could be wrong, but the juxtaposition of cats and some sort of blurry translucent thing just makes me strongly suspect I know who this is... :)', '2010-09-02 14:56:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
