(6151514, 905666, 60915, '<td valign="top">A really nice natural portrait! Although I can''t help feeling he''s thinking what sort of mischief can I get into when this is all over! hehe : )</td>', 'A really nice natural portrait! Although I can''t help feeling he''s thinking what sort of mischief can I get into when this is all over! hehe : )', '2010-09-03 23:48:16.000000', NULL, 1),
(6151519, 905759, 60915, '<td valign="top">Maybe it''s the hood, but I find this a little disturbing. I''m feeling he has bad intentions...<br/>I like when a photo stirs up different emotions! : )</td>', 'Maybe it''s the hood, but I find this a little disturbing. I''m feeling he has bad intentions...I like when a photo stirs up different emotions! : )', '2010-09-03 23:51:28.000000', NULL, 1),
(6151522, 906149, 60915, '<td valign="top">Nice character portrait, I bet he''d have a few stories to tell.</td>', 'Nice character portrait, I bet he''d have a few stories to tell.', '2010-09-03 23:55:00.000000', NULL, 1),
