(6151670, 905666, 120675, '<td valign="top">I keep coming back to this image. A terrific portrait of an interesting looking young fella. I like your use of colour.</td>', 'I keep coming back to this image. A terrific portrait of an interesting looking young fella. I like your use of colour.', '2010-09-04 07:25:47.000000', NULL, 1),
(6151671, 906371, 120675, '<td valign="top">I love the lines and textures in this image. I want to look at it for ages to explore it further.</td>', 'I love the lines and textures in this image. I want to look at it for ages to explore it further.', '2010-09-04 07:30:51.000000', NULL, 1),
(6151672, 906886, 120675, '<td valign="top">Quite a simple looking image. nixter loves filling the bottom corners and I like your use of it here. The bits of red left on the scooter are great.</td>', 'Quite a simple looking image. nixter loves filling the bottom corners and I like your use of it here. The bits of red left on the scooter are great.', '2010-09-04 07:32:54.000000', NULL, 1),
