(6153983, 905524, 50695, '<td valign="top">An embrace of nix. I love this edge of nothingness, and how you skate it without losing the couple or even the fleeting emotion.<br/> <br/>Posthumous Art Gallery</td>', 'An embrace of nix. I love this edge of nothingness, and how you skate it without losing the couple or even the fleeting emotion. Posthumous Art Gallery', '2010-09-06 22:24:05.000000', NULL, 1),
(6153985, 906485, 50695, '<td valign="top">Perfect exposure for this shot. You accomplish so much with the darkness, and the window is gorgeous.<br/> <br/>Posthumous Art Gallery</td>', 'Perfect exposure for this shot. You accomplish so much with the darkness, and the window is gorgeous. Posthumous Art Gallery', '2010-09-06 22:25:30.000000', NULL, 1),
(6153986, 906856, 50695, '<td valign="top">The title fascinates me. I love how you made the woman as chaotic as the wall... while also blending her into the wall.<br/> <br/>Posthumous Art Gallery</td>', 'The title fascinates me. I love how you made the woman as chaotic as the wall... while also blending her into the wall. Posthumous Art Gallery', '2010-09-06 22:27:00.000000', NULL, 1),
(6153987, 906769, 50695, '<td valign="top">Title gives away your secret. It looks more like a filmy gauze over a gauzy film.<br/> <br/>Posthumous Art Gallery</td>', 'Title gives away your secret. It looks more like a filmy gauze over a gauzy film. Posthumous Art Gallery', '2010-09-06 22:28:07.000000', NULL, 1),
(6153989, 906406, 50695, '<td valign="top">Perfect title. Connects this image to Hiroshima for me. Splendid shot.<br/> <br/>Posthumous Art Gallery</td>', 'Perfect title. Connects this image to Hiroshima for me. Splendid shot. Posthumous Art Gallery', '2010-09-06 22:28:57.000000', NULL, 1),
(6153990, 906864, 50695, '<td valign="top">I''ll be honest. I checked all the nixter self portraits I could find to see if you''re copying him. I see no evidence of that. I think this is a wonderful chaotic figure on the verge of dissolving completely.<br/> <br/>Posthumous Art Gallery</td>', 'I''ll be honest. I checked all the nixter self portraits I could find to see if you''re copying him. I see no evidence of that. I think this is a wonderful chaotic figure on the verge of dissolving completely. Posthumous Art Gallery', '2010-09-06 22:30:17.000000', NULL, 1),
(6153993, 906853, 50695, '<td valign="top">Perfect combination of blur and sharp, energy and engagement.<br/> <br/>Posthumous Art Gallery</td>', 'Perfect combination of blur and sharp, energy and engagement. Posthumous Art Gallery', '2010-09-06 22:31:03.000000', NULL, 1),
(6153995, 905989, 50695, '<td valign="top">This is too pointandshooty for a ribbon and ESPECIALLY for a 10, but for something simply gorgeous to look at, I give you a 9 and put you in the<br/> <br/>Posthumous Art Gallery</td>', 'This is too pointandshooty for a ribbon and ESPECIALLY for a 10, but for something simply gorgeous to look at, I give you a 9 and put you in the Posthumous Art Gallery', '2010-09-06 22:32:49.000000', NULL, 1),
