INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6154283, 905814, 60915, '<td valign="top">This is a great crop and the b&amp;w tones are perfect! : )</td>', 'This is a great crop and the b&w tones are perfect! : )', '2010-09-07 05:23:50.000000', NULL, 1),
(6154284, 906294, 60915, '<td valign="top">Wonderful light and shadow. I love the way kids can entertain themselves and not be concerned what others think... it''s a shame we lose that as we get older. : )</td>', 'Wonderful light and shadow. I love the way kids can entertain themselves and not be concerned what others think... it''s a shame we lose that as we get older. : )', '2010-09-07 05:23:54.000000', NULL, 1),
(6154288, 906557, 60915, '<td valign="top">Dramatic composition! : )</td>', 'Dramatic composition! : )', '2010-09-07 05:30:38.000000', NULL, 1),
(6154289, 906805, 60915, '<td valign="top">Has a voyeuristic feel looking through the poles. I feel like I''m about to be caught looking. Great title too!...I suck at titles! : )</td>', 'Has a voyeuristic feel looking through the poles. I feel like I''m about to be caught looking. Great title too!...I suck at titles! : )', '2010-09-07 05:30:42.000000', NULL, 1),
